MATCH (target:PlantItem {tag: 'T-1-3'})
MATCH (source:PlantItem)-[:send_to*1..]->(target)
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:CheckValve)
WHERE v.unit_id = '1'
RETURN count(*) AS check_valve_count, collect(v.tag) AS tags;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "V-1-4"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: 'T-1-1'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (start:PlantItem {tag: 'V-1-1'}), (finish:PlantItem {tag: 'P-1-2'})
MATCH path = shortestPath((start)-[:send_to*1..]->(finish))
RETURN [item IN nodes(path) WHERE item:Equipment OR item:BallValve OR item:CheckValve OR item:GlobeValve OR item:OperatedValve | item.tag] AS tags_in_order;
